<div class="content-wrapper" style="min-height: 916px;">    <!-- Content Header (Page header) -->    <section class="content-header">        <h1>Thống kê traffic</h1>        <ol class="breadcrumb">            <li><a href="/<?php echo ADMIN_URL; ?>"><i class="fa fa-dashboard"></i> Home</a></li>            <li class="active">Thống kê traffic</li>        </ol>        <div class="box-body">            <div class="form-group" >                          <div class="input-group" style=" width: 50%;margin-right: 10px;float: left">                    <div class="input-group-addon">                        <i class="fa fa-calendar"></i>                    </div>                    <input  type="text" value="<?php echo $date; ?>" class="form-control pull-right" id="date_install"/>                </div>                <select class="form-control" id="order" style="float: left;width: 25%;">                    <option value="buyed DESC">Số lượng mua</option>                    <option value="view DESC">Lượt view</option>                </select>            </div>           </div>       </section>        <!-- Main content -->    <section class="content">        <div class="row">            <div class="col-xs-12">                <div class="box" id="list_ajax">                </div>            </div><!-- /.box -->        </div><!-- /.col -->    </section></div><!-- /.row --><script>    function loadlist() {        var date_install = $('#date_install').val();        var order = $('#order').val();        $.post('/<?php echo ADMIN_URL; ?>report/get_list_traffic', {date_install: date_install, order: order}, function (results) {            $('#list_ajax').html(results);        });    }    $('#order').change(function(){        loadlist();    });    $("#date_install").daterangepicker({format: 'DD/MM/YYYY', });    $('#date_install').change(function () {        loadlist();    });    loadlist();</script>